def arbitrate_packet(seq_num, next_expected_seq):
    if seq_num < next_expected_seq:
        return 'DROP_DUPLICATE'
    if seq_num == next_expected_seq:
        return 'PROCESS_IN_ORDER'
    return 'GAP_DETECTED'

