    # Dedicated isolated core (isolcpus) polls NIC DMA ring with zero syscalls
    packets = rx_ring.poll_dma_burst(max_burst)
    for pkt in packets:
        decode_and_arbitrate(pkt)

def handle_gap(seq_num, expected_seq, reorder_buf, replay_client):
    reorder_buf[seq_num] = raw_packet
    if not replay_client.in_flight(expected_seq):
        replay_client.request_range(expected_seq, seq_num - 1)
    if len(reorder_buf) > 1024:
        resync_from_snapshot()  # Bounded buffer safety

def decode_itch_add_order(frame_bytes):
    # Fixed-offset struct unpack: order_ref(Q), side(c), shares(I), stock(8s), price(I)
    if len(frame_bytes) < 36:
        raise ValueError('Truncated ITCH frame')
    order_ref, side, shares, stock, price_int = struct.unpack('>QcI8sI', frame_bytes[11:36])
    return {'order_ref': order_ref, 'side': side.decode(), 'shares': shares, 'price': price_int / 10000.0}

# Conceptual SPSC push with power-of-2 bitmask
def spsc_push(ring, write_idx, read_idx_cached, item, mask):
    if (write_idx + 1) & mask == read_idx_cached:
        return False  # Ring full: apply slow-consumer policy
    ring[write_idx & mask] = item
    return True

class PriceLevel:
    def __init__(self, price):
        self.price = price
        self.total_qty = 0
        self.orders = {}  # order_id -> qty (doubly-linked list in C++)
    def cancel(self, order_id):
        qty = self.orders.pop(order_id, 0)
        self.total_qty -= qty

